# Aggregate products per basket: count of products, sum/nunique etc.
# Build aggregations dynamically based on available columns
aggregations = {
    'product_id': ['count', 'nunique']
}
if 'price' in products_df.columns:
    aggregations['price'] = ['sum', 'mean']
if 'quantity' in products_df.columns:
    aggregations['quantity'] = ['sum']
if 'category' in products_df.columns:
    aggregations['category'] = ['nunique']

agg_products = products_df.groupby('basket_ID').agg(aggregations).reset_index()
# Flatten multi-level column names
agg_products.columns = ['_'.join(col).strip('_') if isinstance(col, tuple) else col for col in agg_products.columns]

# Merge aggregated features to main table
if 'basket_ID_' in agg_products.columns:
    df = main_df.merge(agg_products, left_on='ID', right_on='basket_ID_', how='left')
else:
    df = main_df.merge(agg_products, left_on='ID', right_on='basket_ID', how='left')
